import { renderOpenApplicationsPage, renderOpenFormPage, renderOpenServices, renderOpenHistorySection, mountOpenApplications } from './open-applications.js?v=academy-2';
import { mountAccountDepartment } from './account-department.js?v=academy-1';
import { renderSeniorReportPage, renderSeniorReportService, renderSeniorReportHistorySection, mountSeniorReports } from './senior-reports.js?v=academy-1';
import { renderInternalTransferPage, renderInternalTransferService, renderInternalTransferHistorySection, mountInternalTransfers } from './internal-transfers.js?v=academy-1';
import { initAccount, getAccountState } from './auth-client.js?v=academy-1';
import { renderApplicationsPage, renderReinstatementPage, renderAccountPage, mountApplicationPage } from './applications.js?v=academy-1';
import { departments, ranks, staffTopics, floors } from './data/portal.js?v=rank-roles-1';
import { renderReferenceHome, renderReferenceHeader } from './home.js?v=academy-1';
import { renderTransferPage, renderTransferService, renderTransferHistorySection, mountTransfers } from './transfers.js?v=academy-1';
import { startBoot, animatePage } from './motion.js';
let motionCleanup, sceneCleanup, applicationCleanup, currentRoutePath=null;

const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm = s => String(s ?? '').toLocaleLowerCase('ru').replace(/ё/g,'е').replace(/стать(?:ей|[яиюе])/gu,'статья').replace(/[«»“”"']/g,'').replace(/\s+/g,' ').trim();
let mapObserver; let db, searchIndex = [], activeFloor = 1, mapScale = 1, mapX = 0, mapY = 0, routeVersion = 0;
const roman = ['I','II','III','IV','V','VI','VII','VIII','IX','X'];

function icon(type, size=24) {
 const shapes={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M5 19 19 5M5 5h14v14"/>',shield:'<path d="m12 2 8 3v6c0 5-3 8-8 11-5-3-8-6-8-11V5l8-3Z"/><path d="m8 12 3 3 5-6"/>',book:'<path d="M12 5C9 3 5 3 2 4v15c3-1 7-1 10 1 3-2 7-2 10-1V4c-3-1-7-1-10 1Zm0 0v15"/>',network:'<circle cx="12" cy="5" r="3"/><circle cx="5" cy="19" r="3"/><circle cx="19" cy="19" r="3"/><path d="m10 8-4 8m8-8 4 8M8 19h8"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 1v5m0 12v5M1 12h5m12 0h5"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5 5-3Z"/>',academy:'<path d="m1 8 11-5 11 5-11 5L1 8Zm4 3v6c4 3 10 3 14 0v-6m4-3v10"/>',map:'<path d="m2 5 6-3 8 3 6-3v17l-6 3-8-3-6 3V5Zm6-3v17m8-14v17"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',file:'<path d="M6 2h8l5 5v15H6V2Zm8 0v6h5M9 12h7m-7 4h7"/>',menu:'<path d="M3 7h18M3 12h18M3 17h18"/>',chevron:'<path d="m9 5 7 7-7 7"/>',uniform:'<path d="m8 3-6 4 4 5 2-2v12h8V10l2 2 4-5-6-4-4 4-4-4Z"/>',check:'<path d="m4 12 5 5L20 6"/>'};
 return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[type]||shapes.file}</svg>`;
}
const arrow=()=>icon('arrow',20);
const docById = id => db.documents.find(d=>d.id===id);
function sourceHref(id='charter', ref='', needle='') {
 const doc=docById(id); if(!doc) return '#/documents';
 const n=roman.indexOf(String(ref).split('.')[0]);
 const chapter=n>=0?doc.chapters[n]:null;
 const blocks=chapter?chapter.blocks:doc.chapters.flatMap(c=>c.blocks);
 const suffix=String(ref).replace(/^[IVX]+\.?/,'').split(/[ /–]/)[0];
 let block=needle?blocks.find(b=>norm(b.text).includes(norm(needle))):null;
 if(!block&&suffix) block=blocks.find(b=>new RegExp(`(^|\\n)\\s*-?\\s*${suffix.replace(/\./g,'\\.')}[.\\s]`).test(b.text));
 return `#/documents/${id}${block?'?anchor='+block.id:chapter?'?section='+chapter.id:''}`;
}
function sourceLink(ref,label,id='charter',needle='') {return `<a class="source-link" href="${sourceHref(id,ref,needle)}">${esc(label||'Устав · '+ref)} ${arrow()}</a>`;}
function sourceLinks(d){return d.sources.map(([id,ref,label,needle])=>sourceLink(ref,label,id,needle)).join('');}
function heading(kicker,title,description='',parent='') {return `<div class="container page-heading"><div class="breadcrumb"><a href="#/">Главная</a>${parent?`<span>/</span>${parent}`:''}<span>/</span><span>${esc(kicker)}</span></div><div class="section-kicker">${esc(kicker)}</div><h1 class="page-title">${title}</h1>${description?`<p class="page-description">${description}</p>`:''}</div>`;}
function panel(title,text,link=''){return `<article class="info-card"><h3 class="info-title">${title}</h3><p class="info-text">${text}</p>${link}</article>`;}
function header(path) { $('#header').innerHTML=renderReferenceHeader({path,icon,account:getAccountState()}); }

const gameNotice = `<section class="container footer-game-notice" aria-labelledby="footer-game-notice-title"><h2 id="footer-game-notice-title">Неофициальный игровой проект</h2><p>Сайт создан исключительно для ролевой игры GTA 5 RP в проекте «Россия Онлайн». Он не является официальным сайтом ФСБ России или других государственных органов, не связан с ними, не уполномочен действовать от их имени и не представляет их интересы.</p><p>Все размещённые здесь звания, должности, регламенты, документы и заявки относятся только к игровому процессу. Материалы не являются официальными нормативными актами, служебными документами или юридической консультацией. Через сайт не оказываются государственные услуги и не принимаются официальные обращения.</p><p>Используйте в формах только данные игровых персонажей. Не отправляйте настоящие паспорта, удостоверения и другие реальные документы.</p></section>`;
function footer(){ $('#footer').innerHTML=`<div class="container footer-inner"><div class="footer-brand"><a href="#/" class="brand"><img class="brand-mark" src="assets/emblem.svg?v=applications-1" width="42" height="48" alt=""><span class="brand-text"><span class="brand-name">ФСБ</span><span class="brand-sub">ИГРОВАЯ ФРАКЦИЯ</span></span></a><p>Портал игровой фракции «Россия Онлайн».<br>Справочник и заявки для GTA 5 RP.</p></div><div class="footer-nav"><span class="eyebrow">НАВИГАЦИЯ</span><a href="#/departments">Управления</a><a href="#/applications">Заявки</a><a href="#/applications/academy">Поступление в академию</a><a href="#/applications/transfer">Переводы в ФСБ</a><a href="#/applications/internal-transfer">Между отделами</a><a href="#/applications/senior-report">Отчёт старших</a><a href="#/account">Аккаунт</a><a href="#/staff">Справочник сотрудника</a><a href="#/newcomer">Академия и начало службы</a></div><div class="footer-nav"><span class="eyebrow">МАТЕРИАЛЫ</span><a href="#/documents/charter">Устав ФСБ</a><a href="#/documents/law">Федеральный закон</a><a href="#/building">Схема учреждения</a></div></div>${gameNotice}<div class="container footer-bottom"><span>Неофициальный сайт игровой фракции. GTA 5 RP.</span><a href="#/editorial">Источники и редакционные замечания ↗</a><button class="text-link ref-replay" data-action="replay-intro">Повторить заставку ↗</button><span>РОССИЯ ОНЛАЙН / 2026</span></div>`;}

function deptCard(d,compact=false){return `<a class="dept-card ${compact?'compact':''}" href="#/departments/${d.id}"><div class="dept-cover"><img src="assets/${d.image}" alt="${d.id==='alpha'?'Комплекты формы «Альфы»':'Атмосферная игровая иллюстрация'}" loading="lazy" style="object-position:${d.position}"><span class="dept-number">${d.number} / ${d.id==='academy'?'УКП':'УПРАВЛЕНИЕ'}</span><span class="dept-symbol">${esc(d.code)}</span></div><div class="dept-body"><span class="dept-code">${esc(d.short)}</span><h3 class="dept-name">${esc(d.name)}</h3><p class="dept-description">${esc(d.description)}</p><div class="dept-footer"><span>О подразделении</span>${arrow()}</div></div></a>`;}
function home(){return renderReferenceHome({departments,ranks,icon,sourceLink,documentCards});}

function documentCards(){const counts={charter:'10 глав',law:'4 главы · 18 статей','regulation-m':'13 разделов'};return `<div class="document-card-grid">${db.documents.map((d,i)=>`<a class="document-card" href="#/documents/${d.id}"><span class="doc-number">0${i+1} / ДОКУМЕНТ</span>${icon('file',32)}<h3 class="doc-title">${esc(d.title)}</h3><p class="doc-description">${esc(d.subtitle||'Полный текст предоставленного игрового документа.')}</p><div class="doc-footer"><span>${counts[d.id]}</span>${arrow()}</div></a>`).join('')}</div>`;}
function departmentList(){return heading('УПРАВЛЕНИЯ','У каждого — своя задача.','Пять управлений и Академия ФСБ. Найдите своё подразделение, изучите обязанности и связанные документы.')+`<section class="container section section-tight"><div class="dept-grid">${departments.map(d=>deptCard(d)).join('')}</div><div class="notice">Академия — подотдел УКП. Общие обязанности действуют для всех сотрудников наряду со специализацией управления. ${sourceLink('II.6','Основание · устав, глава II')}</div></section>`;}
function departmentDetail(id){const d=departments.find(x=>x.id===id);if(!d)return notFound();return heading(d.name,esc(d.short),esc(d.description),'<a href="#/departments">Управления</a>')+`<section class="container section section-tight"><div class="content-grid"><aside class="sidebar"><span class="eyebrow">СТРУКТУРА ФСБ</span><nav class="sidebar-nav">${departments.map(x=>`<a class="sidebar-link ${x.id===id?'active':''}" href="#/departments/${x.id}">${esc(x.name)}${x.id==='academy'?'<small>Подотдел УКП</small>':''}</a>`).join('')}</nav><a class="source-link" href="#/staff?tab=general">Общие обязанности ${arrow()}</a></aside><div><div class="department-banner"><img src="assets/${d.image}" alt="${id==='alpha'?'Предоставленные комплекты формы управления «А»':'Атмосферная игровая иллюстрация'}" style="object-position:${d.position}"><span class="department-banner-code">${esc(d.code)}</span></div><div class="section-kicker">НАЗНАЧЕНИЕ И ЗАДАЧИ</div><h2 class="section-title">Направления работы</h2><ol class="task-list">${d.tasks.map((t,i)=>`<li><span>0${i+1}</span><p>${esc(t)}</p></li>`).join('')}</ol><div class="panel"><h3>Место в структуре</h3><p>${esc(d.extra)}</p>${id==='ukp'?'<a class="text-link" href="#/departments/academy">Академия ФСБ '+arrow()+'</a>':id==='academy'?'<a class="text-link" href="#/departments/ukp">Управление кадров и подготовки '+arrow()+'</a>':''}</div><div class="section-heading"><h2 class="section-title small">Полномочия и ограничения</h2></div><ul class="check-list">${d.limits.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${id==='m'?`<div class="info-grid">${panel('УСБ-М','Территориальный контроль госорганов и координация внутренних подразделений в пределах предоставленного положения.')}${panel('УСБ ФСБ','Входит в УСБ-М. Внутренний контроль центрального аппарата ФСБ; полномочия определены отдельными разделами положения.')}</div>`:''}<div class="panel"><h3>Форма и экипировка</h3><p>${id==='alpha'?'Два утверждённых комплекта и допустимые изменения — в отдельной памятке.':'Общие требования — глава VI устава. Отдельный визуальный регламент для этого подразделения владельцем не предоставлен.'}</p><a class="text-link" href="${id==='alpha'?'#/uniform':sourceHref('charter','VI')}">${id==='alpha'?'Посмотреть комплекты «Альфы»':'Общие правила формы'} ${arrow()}</a></div><h2 class="section-title small">Связанные документы</h2><div class="link-list">${sourceLinks(d)}${sourceLink('II.5.13','Обязанности всех сотрудников')}${sourceLink('II.4','Должности и подчинённость')}</div></div></div></section>`;}
function staffPage(params){const selected=params.get('tab')||'general';const t=staffTopics.find(x=>x.id===selected)||staffTopics[0];return heading('СОТРУДНИКАМ','Ясность в каждом действии.','Рабочий справочник: общие правила, иерархия, график и служебное взаимодействие.')+`<section class="container section section-tight"><div class="content-grid"><aside class="sidebar"><span class="eyebrow">СПРАВОЧНИК</span><nav class="sidebar-nav">${staffTopics.map(x=>`<a class="sidebar-link ${x.id===t.id?'active':''}" href="#/staff?tab=${x.id}">${esc(x.label)}</a>`).join('')}</nav><div class="sidebar-note">Краткие пояснения.<br>Полные нормы — в документах.</div></aside><div><h2 class="section-title">${esc(t.title)}</h2><p class="section-intro wide">${esc(t.intro)}</p>${t.id==='hierarchy'?hierarchy():`<div class="info-grid">${t.items.map(([title,text,ref])=>panel(esc(title),esc(text),sourceLink(ref))).join('')}</div>`}${t.id==='schedule'?'<div class="notice">Условия добровольных ночных мероприятий и отзыва с отдыха сформулированы неоднозначно. Эта памятка не определяет автоматически обязанность выйти на службу.</div>':''}<div class="panel"><h3>Правила вашего управления</h3><p>Задачи подразделения, специальные ограничения и связанные материалы.</p><a class="text-link" href="#/departments">Выбрать управление ${arrow()}</a></div></div></div></section>`;}
function hierarchy(){let last='';return `<div class="rank-table"><table><thead><tr><th>Должность</th><th>Звание</th></tr></thead><tbody>${ranks.map(([group,title,rank])=>{let row=group!==last?`<tr class="rank-group"><th colspan="2">${group}</th></tr>`:'';last=group;return row+`<tr><td>${esc(title)}</td><td>${esc(rank)}</td></tr>`;}).join('')}</tbody></table></div><div class="notice">Должности в таблице обновлены по уточнению руководства. У старшего состава своего управления преимущество в приказе перед старшим составом другого управления.</div>${sourceLink('II.4','Устав · глава II')}<h3 class="section-title small">Обязанности по должностям</h3><div class="link-list">${[['Советник директора','II.5.1'],['Руководитель управления','II.5.3'],['Советник управления','II.5.5'],['Начальник управления','II.5.7'],['Заместитель начальника','II.5.9'],['Инструктор','II.5.11']].map(([label,ref])=>sourceLink(ref,label)).join('')}</div>`;}

function documentsPage(){return heading('ДОКУМЕНТЫ','Знать основания.<br>Понимать границы.','Полные тексты игровых нормативных документов. Удобное чтение, поиск и прямые ссылки на нужные пункты.')+`<section class="container section section-tight documents-page">${documentCards()}<div class="panel split-panel"><div><span class="section-kicker">НАЙТИ НУЖНУЮ НОРМУ</span><h2 class="section-title small">Один поиск по всем документам</h2><p>Введите тему или фразу. Результат откроется на конкретном абзаце.</p></div><button class="button primary" data-action="open-search">Поиск по материалам ${icon('search',18)}</button></div><div class="notice">Это документы игрового проекта «Россия Онлайн». Даты редакций закона, устава и положения «М» в источниках не указаны. Дата 26.09.2026 относится только к форме «Альфы».</div><a class="text-link" href="#/editorial">Источники, поправка и редакционные замечания ${arrow()}</a></section>`;}
function reader(id,params){const d=docById(id);if(!d)return notFound();const anchor=params.get('anchor');const section=params.get('section');const active=d.chapters.find(c=>c.id===section||c.blocks.some(b=>b.id===anchor))||d.chapters[0];const blocks=bs=>bs.map(b=>b.kind==='heading'?`<h3 class="document-block doc-subheading" id="${esc(b.id)}">${esc(b.text)}</h3>`:`<p class="document-block" id="${esc(b.id)}">${esc(b.text)}</p>`).join('');return heading('НОРМАТИВНАЯ БАЗА',esc(d.title),esc(d.subtitle||'Полный текст предоставленного игрового документа.'),'<a href="#/documents">Документы</a>')+`<section class="container section section-tight reader-page" data-document="${esc(id)}"><div class="document-toolbar"><span class="badge">ИГРОВОЙ ДОКУМЕНТ РО</span><span class="muted">Дата редакции не указана</span><div class="toolbar-actions"><button class="icon-button" data-action="font" data-size="-1" aria-label="Уменьшить шрифт">А−</button><button class="icon-button" data-action="font" data-size="1" aria-label="Увеличить шрифт">А+</button><button class="button small secondary" data-action="copy-link">Копировать ссылку</button><button class="button small secondary" data-action="print">Печать</button><a class="button small secondary" href="${esc(d.sourceFile)}" download>Исходник ↓</a></div></div><div class="content-grid"><aside class="sidebar document-sidebar"><span class="eyebrow">СОДЕРЖАНИЕ</span><nav class="toc">${d.chapters.map(c=>`<a class="toc-link ${c===active?'active':''}" href="#/documents/${d.id}?section=${c.id}">${esc(c.title)}</a>`).join('')}</nav><a class="source-link" href="#/editorial">Примечания к источникам ${arrow()}</a></aside><article class="document-article" style="--reader-size:${getReaderSize()}px;--reader-leading:${getReaderLeading(getReaderSize())}px"><div class="document-meta"><span>ПОЛНЫЙ ТЕКСТ</span><span>${d.chapters.length} ${id==='regulation-m'?'разделов':'глав'}</span></div><div class="document-notice">Нумерация и формулировки сохранены по предоставленному источнику. Краткие пояснения на других страницах не заменяют полный текст.</div>${id==='law'?`<div class="notice amendment-note"><strong>Статья 10, пункт «ж»</strong><p>Ссылка на подследственность по статье 80 УПК РО уже учтена. Текст статьи 80 не предоставлен.</p><a href="#/editorial?tab=amendment">Посмотреть уточнение ↗</a></div>`:''}${blocks(d.intro||[])}${d.chapters.map(c=>`<section class="document-chapter" id="${esc(c.id)}"><div class="chapter-heading"><span class="section-kicker">${esc(c.label||'РАЗДЕЛ')}</span><h2>${esc(c.title)}</h2><button class="icon-button" data-action="copy-anchor" data-anchor="${c.id}" data-doc="${d.id}" aria-label="Скопировать ссылку на раздел">↗</button></div>${blocks(c.blocks)}</section>`).join('')}<div class="document-end">КОНЕЦ ДОКУМЕНТА · ${esc(d.title)}</div></article></div></section>`;}

function uniformPage(){return heading('ФОРМА И ЭКИПИРОВКА','Собранность —<br>в каждой детали.','Форменная одежда управления «А» («Альфа»). Редакция от 26.09.2026.')+`<section class="container section section-tight"><div class="page-meta"><span class="badge">УПРАВЛЕНИЕ «А»</span><span>Согласовано: @А|Андрей Ваеров|33935</span></div><button class="uniform-reference" data-action="lightbox" data-src="assets/alpha-uniform.png" data-caption="Оба комплекта «Альфы» — предоставленное изображение"><img src="assets/alpha-uniform.png" alt="Слева чёрный комплект «Альфы», справа смешанный комплект с камуфляжными брюками"><span>Увеличить оригинал ${icon('search',18)}</span></button><div class="uniform-grid"><article class="uniform-card"><span class="section-kicker">КОМПЛЕКТ №1</span><h2>Чёрный комплект «Альфа»</h2><p>Для ночных операций и случаев, когда нет возможности собрать второй комплект.</p><div class="wardrobe-path">Гардероб <span>→</span> «Боевой комплект ФСБ» <span>→</span> «Изменить»</div></article><article class="uniform-card"><span class="section-kicker">КОМПЛЕКТ №2</span><h2>Смешанный комплект «Альфа»</h2><ol class="compact-steps"><li>Выбрать «Штурмовой комплект (Мультикам)» и заменить маску на чёрную балаклаву.</li><li>В «Боевом комплекте ФСБ» снять и сохранить верх в инвентарь.</li><li>Надеть настроенный «Штурмовой комплект (Мультикам)» и отложенную чёрную рубашку.</li><li>Допускается обратный порядок сборки, если так удобнее.</li><li>Выбрать скин бронежилета №14 или №24.</li></ol></article></div><div class="info-grid">${panel('Допустимые изменения','В обоих комплектах: шлем или кепка, кобура или пояс, перчатки и тактические очки — на усмотрение сотрудника.')}${panel('Цвет ботинок','Для комплекта №2: оливковые или чёрные ботинки. Разрешение на изменение аксессуаров также действует.')}${panel('Свободная форма','Со звания Подполковника. Общие ограничения главы VI устава сохраняются; краткое примечание не объявляет их отменёнными.',sourceLink('VI.2.1'))}${panel('Другие управления','Отдельные визуальные регламенты не предоставлены. Общие правила формы, офисных комплектов и исключений — в главе VI.',sourceLink('VI'))}</div><div class="notice">Дата 26.09.2026 — редакция этого материала о форме «Альфы». Она не является датой редакции всего устава.</div><div class="link-list"><a class="source-link" href="#/departments/alpha">Страница управления «А» ${arrow()}</a>${sourceLink('VI','Полный раздел о форме и экипировке')}</div></section>`;}
function buildingPage(params){activeFloor=Number(params.get('floor'))===2?2:1;const f=floors.find(x=>x.id===activeFloor);return heading('СХЕМА УЧРЕЖДЕНИЯ','Ориентируйтесь уверенно.','Найдите нужное помещение. Схемы сохранены по предоставленным изображениям без изменения планировки.')+`<section class="container section section-tight"><div class="tabs" role="tablist" aria-label="Уровень учреждения">${floors.map(x=>`<a class="tab ${x.id===f.id?'active':''}" role="tab" aria-selected="${x.id===f.id}" href="#/building?floor=${x.id}">${esc(x.title)}</a>`).join('')}</div><div class="map-layout"><aside class="panel map-room-list"><span class="eyebrow">ПОМЕЩЕНИЯ</span>${f.rooms.map(([id,label])=>`<button class="map-room" data-action="map-room" data-room="${id}">${esc(label)} ${icon('chevron',15)}</button>`).join('')}</aside><div><div class="map-toolbar"><div><button class="icon-button" data-action="map-zoom" data-delta="-0.25" aria-label="Уменьшить масштаб">−</button><span id="map-scale">100%</span><button class="icon-button" data-action="map-zoom" data-delta="0.25" aria-label="Увеличить масштаб">+</button><button class="button small secondary" data-action="map-reset">Сбросить</button></div><button class="text-link" data-action="lightbox" data-src="assets/${f.image}" data-caption="${esc(f.title)} — исходная схема">Полная схема ${arrow()}</button></div><div class="map-viewport" tabindex="0" aria-label="Схема. При увеличении перетаскивайте изображение. Стрелки перемещают схему, плюс и минус меняют масштаб."><div class="map-canvas"><img class="map-image" src="assets/${f.image}" alt="${esc(f.title)}: ${esc(f.rooms.map(x=>x[1]).join(', '))}" draggable="false">${f.rooms.map(([id,label,x,y])=>`<button class="map-marker" data-action="map-room" data-room="${id}" style="left:${x}%;top:${y}%" aria-label="${esc(label)}" title="${esc(label)}"><span></span></button>`).join('')}</div></div><div class="map-selected" id="map-selected">Выберите помещение в списке или на схеме.</div><p class="muted map-hint">+ / − — масштаб · Перетаскивание — перемещение · Стрелки — управление с клавиатуры</p></div></div><div class="notice">Обозначение уровней основано на переходе «Второй этаж» на первой схеме. Кабинеты не распределены по управлениям. Метки помогают найти подпись; они не обозначают маршрут или разрешение на доступ.</div></section>`;}
function newcomerPage(){return heading('НОВИЧКУ','Первый день.<br>Правильное начало.','Путеводитель по Академии и основам службы — только по предоставленному уставу.')+`<section class="container section section-tight"><div class="feature-panel"><div class="feature-image"><img src="assets/academy.webp" alt="Атмосферная игровая иллюстрация учебного здания"></div><div class="feature-content"><span class="section-kicker">АКАДЕМИЯ ФСБ</span><h2 class="section-title">Здесь начинается<br>ваш путь.</h2><p>Академия — подотдел УКП. Курсанты получают базовые знания, проходят практику и знакомятся с работой управлений.</p><a class="text-link" href="#/departments/academy">Открыть страницу Академии ${arrow()}</a></div></div><div class="section-heading"><h2 class="section-title">От обучения к опыту</h2></div><ol class="steps">${[['Курс молодого бойца','Первичная подготовка в рядах организации.'],['Лекции и подготовка','Изучение материалов и правил службы.'],['Экзамены','Теоретические и практические испытания.'],['Стажировка','После прохождения двух курсов — направление в управления.']].map(([t,p],i)=>`<li class="step"><span class="step-number">0${i+1}</span><div><h3 class="step-title">${t}</h3><p class="step-text">${p}</p></div></li>`).join('')}</ol>${sourceLink('II.6','Основание · описание Академии','charter','Академия ФСБ')}<div class="section-heading"><h2 class="section-title">Что изучить в первую очередь</h2></div><div class="quick-grid">${[['Устав','/documents/charter','Основные правила службы'],['Субординация','/staff?tab=subordination','Как обращаться и докладывать'],['Структура','/departments','Чем занимаются управления'],['Учреждение','/building','Где находятся помещения']].map(([t,l,d],i)=>`<a class="quick-card" href="#${l}"><span class="quick-number">0${i+1}</span><h3>${t}</h3><p>${d}</p>${arrow()}</a>`).join('')}</div><div class="notice">Для курсантов действуют ограничения выхода с территории и предусмотренные исключения. ${sourceLink('IX.1.3','Прочитать правило')}</div><div class="panel"><span class="badge">ИНФОРМАЦИЯ ОЖИДАЕТСЯ</span><h2 class="section-title small">Как подать заявку?</h2><p>Условия поступления, ссылка на форму и контакты инструкторов пока не предоставлены владельцем портала. После их публикации здесь появится порядок подачи заявки.</p></div><div class="faq"><details><summary>Академия — отдельное управление?</summary><p>Академия является подотделом управления кадров и подготовки (УКП).</p></details><details><summary>Когда начинаются стажировки?</summary><p>В описании Академии указано направление в управления после прохождения двух курсов. Подробное расписание не предоставлено.</p></details><details><summary>Где узнать актуальную форму?</summary><p>Общие правила — глава VI устава. Для управления «А» предоставлена отдельная памятка с двумя комплектами.</p><a href="#/uniform">Форма и экипировка ↗</a></details></div></section>`;}

function buildSearch(){searchIndex=[];db.documents.forEach(d=>{[...(d.intro||[]),...d.chapters.flatMap(c=>c.blocks.map(b=>({...b,chapter:c.title})))].forEach(b=>searchIndex.push({type:'documents',title:b.kind==='heading'?b.text:d.title,context:b.chapter||d.title,text:b.text,url:`#/documents/${d.id}?anchor=${b.id}`}));});departments.forEach(d=>searchIndex.push({type:'departments',title:d.name,context:d.short,text:[d.description,...d.tasks,...d.limits,d.extra].join(' '),url:`#/departments/${d.id}`}));staffTopics.forEach(t=>t.items.forEach(([title,text])=>searchIndex.push({type:'staff',title,context:t.label,text,url:`#/staff?tab=${t.id}`})));searchIndex.push({type:'staff',title:'Комплекты формы «Альфы»',context:'Форма и экипировка',text:'Редакция от 26.09.2026. Согласовано с куратором управления А Андрей Ваеров 33935. Чёрный комплект Альфа для ночных операций. Гардероб Боевой комплект ФСБ Изменить. Смешанный Штурмовой комплект Мультикам чёрная балаклава рубашка. Бронежилет скин 14 24. Головной убор шлем кепка аксессуар кобура пояс перчатки тактические очки. Оливковые чёрные ботинки для второго комплекта. Свободный дресс-код со звания Подполковника.',url:'#/uniform'},{type:'staff',title:'Должности и звания',context:'Справочник сотрудника',text:ranks.flat().join(' '),url:'#/staff?tab=hierarchy'},{type:'staff',title:'Схема учреждения',context:'Помещения',text:floors.flatMap(f=>f.rooms.map(r=>r[1])).join(' '),url:'#/building'});}
function findResults(q,type='all'){const words=norm(q).split(' ').filter(Boolean);if(!words.length)return[];return searchIndex.filter(r=>(type==='all'||r.type===type)&&words.every(w=>norm(r.title+' '+r.text+' '+r.context).includes(w))).map(r=>({...r,score:(norm(r.title).includes(norm(q))?30:0)+words.reduce((n,w)=>n+(norm(r.title).includes(w)?5:0)+(norm(r.context).includes(w)?2:0),0)})).sort((a,b)=>b.score-a.score);}
function highlight(text,q){const words=norm(q).split(' ').filter(Boolean);let str=String(text);let start=words.length?norm(str).indexOf(words[0]):-1;if(str.length>250){start=Math.max(0,start-70);str=(start?'…':'')+str.slice(start,start+250)+'…';}const pattern=words.map(w=>w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/е/g,'[её]')).join('|');if(!pattern)return esc(str);const rx=new RegExp(pattern,'giu');let out='',pos=0;for(const m of str.matchAll(rx)){out+=esc(str.slice(pos,m.index))+`<mark>${esc(m[0])}</mark>`;pos=m.index+m[0].length;}return out+esc(str.slice(pos));}
function resultHTML(q,type='all',limit=60){const res=findResults(q,type);if(!norm(q))return '<div class="empty-state">Введите тему, название управления или фразу из документа.</div>';if(!res.length)return '<div class="empty-state"><h3>Совпадений пока нет</h3><p>Попробуйте более короткий запрос: «отпуск», «субординация» или «Альфа».</p></div>';return `<p class="results-count">Найдено: ${res.length}${res.length>limit?` · показаны первые ${limit}`:''}</p>${res.slice(0,limit).map(r=>`<a class="search-result" href="${r.url}"><span class="eyebrow">${esc(r.context)}</span><h3>${highlight(r.title,q)}</h3><p>${highlight(r.text,q)}</p><span class="search-result-arrow">${arrow()}</span></a>`).join('')}`;}
function searchPage(params){const q=params.get('q')||'',type=params.get('type')||'all';return heading('ПОИСК','Нужная информация — ближе.','Поиск по полным текстам документов, управлениям и справочнику сотрудника.')+`<section class="container section section-tight search-page"><form id="page-search-form" class="search-field"><input class="search-input" id="page-search-input" type="search" value="${esc(q)}" placeholder="Например: отпуск, Альфа, подследственность" aria-label="Поиск по порталу"><button class="button primary" type="submit">Найти ${arrow()}</button></form><div class="search-filters">${[['all','Все материалы'],['documents','Документы'],['departments','Управления'],['staff','Сотрудникам']].map(([id,label])=>`<a class="filter-chip ${type===id?'active':''}" href="#/search?q=${encodeURIComponent(q)}&type=${id}">${label}</a>`).join('')}</div><div class="search-results">${resultHTML(q,type)}</div></section>`;}
function editorialPage(){return heading('ИСТОЧНИКИ И РЕДАКЦИЯ','Точность важнее догадок.','Портал основан на материалах владельца. Здесь собраны известные неоднозначности и история уточнения закона.')+`<section class="container section section-tight editorial-page"><div class="notice">Неоднозначные места сохранены в полных текстах. Пояснения не устанавливают новые игровые правила и не разрешают противоречия вместо руководства проекта.</div><div class="panel" id="amendment"><span class="section-kicker">ГЛАВА III · СТАТЬЯ 10 · ПУНКТ «Ж»</span><h2 class="section-title small">Дознание и следствие — по подследственности</h2><p>История «было/стало» приведена по сообщению владельца. Присланный файл уже содержит новую формулировку. Дата принятия поправки не указана.</p><div class="amendment-grid"><div><span class="eyebrow">БЫЛО · ПО СООБЩЕНИЮ ВЛАДЕЛЬЦА</span><p>${esc(db.amendment.before)}</p></div><div><span class="eyebrow">АКТУАЛЬНЫЙ ТЕКСТ ИСТОЧНИКА</span><p>${esc(db.amendment.after)}</p></div></div><p class="muted">«15.1» — название изменения в сообщении, а не новая статья закона. Текст статьи 80 УПК РО не предоставлен.</p>${sourceLink('','Открыть норму в законе','law','ж) Осуществлять')}</div><h2 class="section-title small">Редакционные замечания</h2><div class="faq">${db.notes.map((n,i)=>`<details><summary><span>${String(i+1).padStart(2,'0')}</span> ${esc(n.title)}</summary><p>${esc(n.text)}</p></details>`).join('')}</div><h2 class="section-title small">Исходные материалы</h2><div class="link-list">${db.documents.map(d=>`<a class="source-link" href="${esc(d.sourceFile)}" download>${esc(d.title)} · TXT ↓</a>`).join('')}<a class="source-link" href="sources/owner-notes.md" download>Уточнения владельца · MD ↓</a><a class="source-link" href="sources/editorial-notes.md" download>Результат анализа · MD ↓</a></div><div class="notice">Атмосферные обложки созданы специально для сайта и не являются скриншотами сервера. Изображение формы и схемы учреждения предоставлены владельцем. Эмблема портала — авторская стилизация для игрового проекта.</div></section>`;}
function notFound(){return heading('СТРАНИЦА НЕ НАЙДЕНА','Здесь пока нет раздела.','Вернитесь на главную или воспользуйтесь поиском.')+'<div class="container section"><a class="button primary" href="#/">На главную '+arrow()+'</a></div>';}

const readerSizes=[16,18,20,24];
function getReaderSize(){try{const saved=Number(localStorage.getItem('fsb-reader-size'));return saved?readerSizes.filter(size=>size<=saved).at(-1)||16:18;}catch{return 18;}}
function getReaderLeading(size){return size===16?24:size===24?32:28;}
function route(){const raw=(location.hash.slice(1)||'/').split('?');return{path:raw[0],params:new URLSearchParams(raw[1]||'')};}
function render(){if(!db)return;const {path,params}=route();if(path==='/'&&currentRoutePath==='/'&&params.get('section')&&document.getElementById(params.get('section'))){$('#mobile-menu').hidden=true;document.querySelector('.menu-toggle')?.setAttribute('aria-expanded','false');document.getElementById(params.get('section')).scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});document.querySelectorAll('.ref-nav .nav-link').forEach(a=>a.classList.toggle('active',a.hash===location.hash));return;}mapObserver?.disconnect();motionCleanup?.();sceneCleanup?.();applicationCleanup?.();applicationCleanup=null;motionCleanup=null;sceneCleanup=null;routeVersion++;header(path);footer();let html,title='';if(path==='/'){html=home();title='Главная';}else if(path==='/departments'){html=departmentList();title='Управления';}else if(path.startsWith('/departments/')){html=departmentDetail(path.split('/')[2]);title=departments.find(d=>d.id===path.split('/')[2])?.name;}else if(path==='/applications'){html=renderOpenApplicationsPage();title='Заявки';}else if(path==='/applications/academy'){html=renderOpenFormPage('academy');title='Академия ФСБ';}else if(path==='/applications/reinstatement'){html=renderOpenFormPage('restoration');title='Восстановление';}else if(path==='/applications/transfer'){html=renderOpenFormPage('transfer');title='Переводы в ФСБ';}else if(path==='/applications/internal-transfer'){html=renderOpenFormPage('internal_transfer');title='Переводы между отделами';}else if(path==='/applications/senior-report'){html=renderOpenFormPage('senior_report');title='Отчёт старших';}else if(path==='/account'){html=renderAccountPage(params);title='Аккаунт';}else if(path==='/staff'){html=staffPage(params);title='Сотрудникам';}else if(path==='/documents'){html=documentsPage();title='Документы';}else if(path.startsWith('/documents/')){html=reader(path.split('/')[2],params);title=docById(path.split('/')[2])?.title;}else if(path==='/uniform'){html=uniformPage();title='Форма и экипировка';}else if(path==='/building'){html=buildingPage(params);title='Схема учреждения';}else if(path==='/newcomer'){html=newcomerPage();title='Новичку';}else if(path==='/search'){html=searchPage(params);title='Поиск';}else if(path==='/editorial'){html=editorialPage();title='Источники и редакция';}else html=notFound();if(path==='/account'&&getAccountState().profile)html+=`<section class="container portal-page transfer-account" data-transfer-account>${renderTransferHistorySection()}</section>`;if(path==='/account')html+=`<section class="container portal-page transfer-account" data-internal-account>${renderInternalTransferHistorySection()}</section>`;if(path==='/account'&&getAccountState().profile)html+=`<section class="container portal-page transfer-account" data-senior-account>${renderSeniorReportHistorySection()}</section>`;if(path==='/account'&&getAccountState().profile)html+=`<section class="container portal-page">${renderOpenServices()}</section>${renderOpenHistorySection()}`;$('#main').innerHTML=html;currentRoutePath=path;if(path==='/account')applicationCleanup=mountApplicationPage({path,params,onStateChange:render});if(path==='/account'){const originalCleanup=applicationCleanup;const transferCleanup=mountTransfers({onStateChange:render});applicationCleanup=()=>{originalCleanup?.();transferCleanup();};}if(path==='/account'){const originalCleanup=applicationCleanup;const internalCleanup=mountInternalTransfers({onStateChange:render});applicationCleanup=()=>{originalCleanup?.();internalCleanup();};}if(path==='/account'){const originalCleanup=applicationCleanup;const seniorCleanup=mountSeniorReports({onStateChange:render});applicationCleanup=()=>{originalCleanup?.();seniorCleanup();};}if(path==='/account'){const originalCleanup=applicationCleanup;const departmentCleanup=mountAccountDepartment({onStateChange:render});applicationCleanup=()=>{originalCleanup?.();departmentCleanup();};}if(path==='/account'||path.startsWith('/applications')){const previous=applicationCleanup;const openCleanup=mountOpenApplications({onStateChange:render});applicationCleanup=()=>{previous?.();openCleanup();};}motionCleanup=animatePage({isHome:path==='/'});if(path==='/'){const version=routeVersion;window.__portalSceneReady=false;import('./scene.js?v=applications-1').then(({mountHeroScene})=>{if(version===routeVersion&&$('#hero-scene'))sceneCleanup=mountHeroScene($('#hero-scene'));}).catch(err=>{console.warn('3D scene fallback',err);window.__portalSceneReady=true;window.dispatchEvent(new CustomEvent('portal:scene-ready',{detail:{success:false}}));});}else{window.__portalSceneReady=true;window.dispatchEvent(new CustomEvent('portal:scene-ready',{detail:{success:true,mode:'not-required'}}));}window.__portalContentReady=true;window.dispatchEvent(new CustomEvent('portal:content-ready'));document.title=`${title||'Портал'} — ФСБ | Россия Онлайн`;$('#search-dialog').close();$('#lightbox').close();window.scrollTo({top:0,left:0,behavior:'instant'});if(path==='/building')setupMap();const target=params.get('anchor')||params.get('section')||(path==='/editorial'&&params.get('tab')==='amendment'?'amendment':null);if(target){requestAnimationFrame(()=>{const el=document.getElementById(target);if(el){el.scrollIntoView({block:'start',behavior:'instant'});el.classList.add('anchor-highlight');}});} }
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Ссылка скопирована');}catch{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';document.body.append(input);input.select();try{document.execCommand('copy');toast('Ссылка скопирована');}catch{toast('Не удалось скопировать ссылку');}input.remove();}}
function openSearch(){const d=$('#search-dialog');d.showModal();$('#dialog-search-results').innerHTML=resultHTML($('#dialog-search-input').value,'all',8);$('#dialog-search-input').focus();}
function updateMap(){const el=$('.map-canvas');if(el){el.style.transform=`translate(${mapX}px, ${mapY}px) scale(${mapScale})`;$('#map-scale').textContent=Math.round(mapScale*100)+'%';}}
function setupMap(){mapScale=1;mapX=0;mapY=0;updateMap();const viewport=$('.map-viewport');const canvas=$('.map-canvas');const image=$('.map-image');const fit=()=>{if(image.naturalWidth&&image.naturalHeight){canvas.style.width=Math.min(viewport.clientWidth,viewport.clientHeight*image.naturalWidth/image.naturalHeight)+'px';}};image.addEventListener('load',fit,{once:true});fit();mapObserver=new ResizeObserver(fit);mapObserver.observe(viewport);let drag=null;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,ox:mapX,oy:mapY};viewport.setPointerCapture(e.pointerId);viewport.classList.add('dragging');});viewport.addEventListener('pointermove',e=>{if(drag&&mapScale>1){mapX=drag.ox+e.clientX-drag.x;mapY=drag.oy+e.clientY-drag.y;updateMap();}});const stop=()=>{drag=null;viewport.classList.remove('dragging');};viewport.addEventListener('pointerup',stop);viewport.addEventListener('pointercancel',stop);viewport.addEventListener('keydown',e=>{const actions={ArrowLeft:()=>mapX+=35,ArrowRight:()=>mapX-=35,ArrowUp:()=>mapY+=35,ArrowDown:()=>mapY-=35,'+':()=>mapScale=Math.min(3,mapScale+.25),'=':()=>mapScale=Math.min(3,mapScale+.25),'-':()=>mapScale=Math.max(1,mapScale-.25)};if(actions[e.key]){e.preventDefault();actions[e.key]();updateMap();}});}

document.addEventListener('click',e=>{const repeated=e.target.closest('a[href^="#/"]');if(repeated&&repeated.hash===location.hash&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&e.button===0){e.preventDefault();if(repeated.hash==='#/'&&currentRoutePath==='/'){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#search-dialog').close();if($('#mobile-menu'))$('#mobile-menu').hidden=true;}else render();return;}const action=e.target.closest('[data-action]');if(!action)return;const a=action.dataset.action;if(a==='skip-main'){e.preventDefault();$('#main').focus();window.scrollTo({top:0,left:0,behavior:'instant'});return;}if(a==='replay-intro'){if(route().path!=='/'){location.hash='#/';setTimeout(()=>startBoot({force:true}),80);}else{window.scrollTo({top:0,behavior:'instant'});startBoot({force:true});}}if(a==='open-search')openSearch();if(a==='close-search')$('#search-dialog').close();if(a==='menu'){const menu=$('#mobile-menu');menu.hidden=!menu.hidden;action.setAttribute('aria-expanded',String(!menu.hidden));}if(a==='lightbox'){$('#lightbox-image').src=action.dataset.src;$('#lightbox-image').alt=action.dataset.caption;$('#lightbox-caption').textContent=action.dataset.caption;$('#lightbox').showModal();}if(a==='close-lightbox')$('#lightbox').close();if(a==='print')window.print();if(a==='copy-link')copyText(location.href);if(a==='copy-anchor'){const url=new URL(location.href);url.hash=`/documents/${action.dataset.doc}?section=${action.dataset.anchor}`;copyText(url.href);}if(a==='font'){const size=readerSizes[Math.min(readerSizes.length-1,Math.max(0,readerSizes.indexOf(getReaderSize())+Number(action.dataset.size)))];try{localStorage.setItem('fsb-reader-size',String(size));}catch{}const article=$('.document-article');article?.style.setProperty('--reader-size',size+'px');article?.style.setProperty('--reader-leading',getReaderLeading(size)+'px');}if(a==='map-zoom'){mapScale=Math.min(3,Math.max(1,mapScale+Number(action.dataset.delta)));if(mapScale===1){mapX=0;mapY=0;}updateMap();}if(a==='map-reset'){mapScale=1;mapX=0;mapY=0;updateMap();}if(a==='map-room'){const room=floors.find(f=>f.id===activeFloor).rooms.find(r=>r[0]===action.dataset.room);document.querySelectorAll('[data-room]').forEach(el=>el.classList.toggle('active',el.dataset.room===room[0]));$('#map-selected').textContent=room[1];mapScale=1;mapX=0;mapY=0;updateMap();}});
document.addEventListener('submit',e=>{if(e.target.id==='dialog-search-form'||e.target.id==='page-search-form'){e.preventDefault();const input=e.target.querySelector('input');const hash=`#/search?q=${encodeURIComponent(input.value.trim())}`;if(location.hash===hash){$('#search-dialog').close();}else location.hash=hash;}});
$('#dialog-search-input').addEventListener('input',e=>{$('#dialog-search-results').innerHTML=resultHTML(e.target.value,'all',8);});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});
for(const d of [$('#search-dialog'),$('#lightbox')])d.addEventListener('click',e=>{if(e.target===d)d.close();});
window.addEventListener('hashchange',render);
async function init(){startBoot();const accountReady=initAccount();try{const res=await fetch('data/documents.json');if(!res.ok)throw Error('HTTP '+res.status);db=await res.json();buildSearch();render();accountReady.finally(()=>{if(db)render();});}catch(err){console.error(err);window.__portalContentReady=true;window.__portalSceneReady=true;window.dispatchEvent(new CustomEvent('portal:content-ready'));window.dispatchEvent(new CustomEvent('portal:scene-ready'));$('#main').innerHTML='<div class="container section"><h1>Не удалось загрузить материалы</h1><p>Обновите страницу. Для локального запуска откройте сайт через HTTP-сервер по инструкции.</p><button class="button primary" onclick="location.reload()">Обновить страницу</button></div>';}}
init();
